import sys

def solve(queries):
    from bisect import insort, bisect_left
    arr = []; out = []
    for q in queries:
        if q[0] == 1: insort(arr, q[1])
        elif q[0] == 2:
            idx = bisect_left(arr, q[1])
            if idx < len(arr) and arr[idx] == q[1]: arr.pop(idx)
        else: out.append(str(arr[q[1]-1]) if q[1]-1 < len(arr) else "-1")
    return "\n".join(out)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    idx = 0
    q = int(data[idx]); idx += 1
    queries = []
    for _ in range(q):
        t = int(data[idx]); idx += 1
        if t in (1, 2):
            queries.append([t, int(data[idx])]); idx += 1
        else:
            queries.append([t, int(data[idx])]); idx += 1
    print(solve(queries))

